// Disposable PostgreSQL and HTTP fixture. The fixture includes one past and two upcoming visits.
import assert from "node:assert/strict";
const vin="1A000000000000001",root="http://dealer.qa.test:8080",other="http://other.qa.test:8080",desk="/api/test-drives/desk",bookPath="/api/test-drives?vin="+vin;
const call=(path,{host=root,method="GET",admin=false,origin=host,data}={})=>fetch(host+path,{method,headers:{Origin:origin,"Content-Type":"application/json",...(admin?{Authorization:"Basic "+Buffer.from(host===other?"dealer:otherqa":"dealer:qa").toString("base64")}:{})},body:data&&JSON.stringify(data)});
const rows=()=>call(desk,{admin:true}).then(r=>r.json()).then(d=>d.appointments);
const report=()=>call("/api/dealer-marketing",{admin:true}).then(r=>r.json()).then(d=>d.report);
const slots=()=>call(bookPath).then(r=>r.json()).then(d=>d.slots);
const change=(confirmation,revision,action,fields={},options={})=>call(desk,{admin:true,method:"PUT",data:{confirmation,revision,action,note:"",...fields},...options});
const book=d=>call(bookPath,{method:"POST",data:d});
assert.equal((await call(desk)).status,403);
const original=await rows(),past=original.find(row=>row.name==="Past visitor");
const before=await report(),times=await slots();assert.ok(times.length>=5);
const data={requestId:crypto.randomUUID(),slot:times[0],phone:"7405550123",email:"visit@example.test",name:"Visit workflow",message:"Interested in this car."};
const saved=await(await book(data)).json(),id=saved.confirmation;
assert.equal(saved.slot,times[0]);assert.ok(saved.timezone);
assert.equal((await change(id,0,"canceled",{},{admin:false})).status,403);
assert.equal((await change(id,0,"canceled",{},{origin:other})).status,403);
assert.equal((await change(id,0,"canceled",{},{host:other})).status,404);
assert.equal((await change(id,0,"missed")).status,422);
assert.equal((await change(id,0,"reschedule",{slot:"1999-01-01"})).status,422);
const competitor={...data,requestId:crypto.randomUUID(),slot:times[1]};
assert.equal((await book(competitor)).status,201);
assert.equal((await change(id,0,"reschedule",{slot:times[1]})).status,409);
const moved=await Promise.all([change(id,0,"reschedule",{slot:times[2],note:"Confirmed by phone."}),change(id,0,"reschedule",{slot:times[3]})]);
assert.deepEqual(moved.map(r=>r.status).sort(),[200,409]);
const updated=await moved.find(r=>r.ok).json();
let open=await slots();assert.ok(open.includes(data.slot) && !open.includes(updated.slot));
const replay=await(await book(data)).json();assert.equal(replay.slot,updated.slot);assert.equal(replay.confirmation,id);
assert.equal((await call("/api/test-drives/notes?vin="+vin,{method:"POST",data:{slot:data.slot,token:saved.noteToken,field:"tradeIn",answer:"2012 sedan"}})).status,200);
assert.equal((await change(id,1,"canceled",{note:"Shopper called to cancel."})).status,200);
assert.equal((await change(id,1,"canceled")).status,409);
assert.equal((await book(data)).status,409);assert.ok((await slots()).includes(updated.slot));
assert.equal((await book({...data,slot:updated.slot,requestId:crypto.randomUUID(),name:"Replacement visitor"})).status,201);
const visits=await rows(),retained=visits.find(r=>r.confirmation===id);
assert.equal(retained.notes.tradeIn,"2012 sedan");assert.equal(retained.visit.history.length,2);assert.equal(retained.visit.state,"canceled");
assert.ok(!JSON.stringify(visits).includes(saved.noteToken));
assert.equal((await change(past.confirmation,0,"attended")).status,200);
assert.equal((await change(past.confirmation,1,"missed")).status,422);
assert.equal((await change(past.confirmation,1,"missed",{note:"Corrected from the sign-in sheet."})).status,200);
const after=await report();assert.equal(after.bookings,before.bookings+3);
assert.equal(after.visits.missed,before.visits.missed+1);assert.equal(after.visits.attended,before.visits.attended);
assert.equal(after.visits.unrecorded,before.visits.unrecorded-1);
console.log("Passed visit attendance, outcome corrections, two-rooftop access, queue privacy, reschedule conflict, receipt replay, slot release, original notes, cancellation and booking reconciliation.");
